const crypto = require('crypto');
const https = require('node:https');
const http_ = require('node:http');
const { URL } = require('node:url');

function fetch(url, opts = {}) {
  const u = new URL(url);
  const isHttps = u.protocol === 'https:';
  const bodyStr = opts.body != null ? (typeof opts.body === 'string' ? opts.body : JSON.stringify(opts.body)) : null;
  const headers = Object.assign({}, opts.headers || {});
  if (bodyStr != null) headers['content-length'] = Buffer.byteLength(bodyStr);
  const options = {
    method: opts.method || 'GET',
    hostname: u.hostname,
    port: u.port || (isHttps ? 443 : 80),
    path: u.pathname + u.search,
    headers,
  };
  return new Promise((resolve, reject) => {
    const req = (isHttps ? https : http_).request(options, res => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString('utf8');
        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300,
          status: res.statusCode,
          headers: res.headers,
          text: async () => text,
          json: async () => JSON.parse(text),
        });
      });
    });
    req.on('error', reject);
    if (bodyStr != null) req.write(bodyStr);
    req.end();
  });
}

const update = $input.first().json;
const cb = update.callback_query;
if (!cb) throw new Error('Not a callback_query');

const allowedChat = String($env.TELEGRAM_CHAT_ID);
if (String(cb.message?.chat?.id) !== allowedChat) throw new Error('Wrong chat');

const [action, ticketId, prNumber] = (cb.data || '').split(':');
if (!['approve', 'reject'].includes(action) || !ticketId || !prNumber)
  throw new Error('Bad callback_data');

const repo = ($env.TARGET_REPO ?? $env.SKLADPRO_REPO);
const apiUrl = (($env.BACKEND_API_URL ?? $env.SKLADPRO_API_URL) || '').replace(/\/+$/, '');
const secret = ($env.AI_SUPPORT_HMAC_SECRET ?? $env.WEBHOOK_SECRET);
const botToken = $env.TELEGRAM_BOT_TOKEN;

const gh = async (method, path, json) => {
  const res = await fetch(`https://api.github.com${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${$env.GITHUB_PAT}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'ai-support-bot',
      ...(json ? { 'content-type': 'application/json' } : {}),
    },
    body: json ? JSON.stringify(json) : undefined,
  });
  if (!res.ok && res.status !== 204 && res.status !== 405) throw new Error(`GitHub ${method} ${path}: ${res.status} ${(await res.text()).slice(0,300)}`);
  return res.status === 204 ? null : res.json();
};

async function patchTicket(patchBody) {
  const body = JSON.stringify(patchBody);
  const ts = Math.floor(Date.now() / 1000);
  const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
  try {
    await fetch(`${apiUrl}/v1/support/tickets/${encodeURIComponent(ticketId)}`, {
      method: 'PATCH',
      headers: {
        'content-type': 'application/json',
        'x-signature-timestamp': String(ts),
        'x-signature': sig,
      },
      body,
    });
  } catch (_) {}
}

async function tg(method, body) {
  const r = await fetch(`https://api.telegram.org/bot${botToken}/${method}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`Telegram ${method}: ${r.status} ${(await r.text()).slice(0,300)}`);
  return r.json();
}

let resultText;
let resultStatus;
if (action === 'approve') {
  try {
    await gh('PUT', `/repos/${repo}/pulls/${prNumber}/merge`, { merge_method: 'squash' });
    resultStatus = 'merged';
    resultText = `✅ <b>Одобрено и смержено</b> — PR #${prNumber} влит в main.`;
  } catch (err) {
    resultStatus = 'failed';
    resultText = `⚠️ Не удалось смержить PR #${prNumber}: ${err.message}`;
  }
} else {
  try {
    const pr = await gh('GET', `/repos/${repo}/pulls/${prNumber}`);
    await gh('PATCH', `/repos/${repo}/pulls/${prNumber}`, { state: 'closed' });
    try { await gh('DELETE', `/repos/${repo}/git/refs/heads/${pr.head.ref}`); } catch (_) {}
    resultStatus = 'rejected';
    resultText = `❌ <b>Отклонено</b> — PR #${prNumber} закрыт, ветка удалена.`;
  } catch (err) {
    resultStatus = 'failed';
    resultText = `⚠️ Не удалось закрыть PR #${prNumber}: ${err.message}`;
  }
}

await patchTicket({ status: resultStatus });
await tg('answerCallbackQuery', { callback_query_id: cb.id, text: 'OK' });

const originalText = cb.message.text || '';
await tg('editMessageText', {
  chat_id: cb.message.chat.id,
  message_id: cb.message.message_id,
  parse_mode: 'HTML',
  text: originalText + `\n\n———\n${resultText}`,
  reply_markup: { inline_keyboard: [] },
});

return [{ json: { ticketId, prNumber, action, resultStatus } }];
